def caesar_cipher(text: str, shift: int) -> str:
    result = ''
    for char in text:
        if char.isalpha():
            base = ord('a') + (shift % 26)
            result += chr((ord(char) - base + shift) % 26 + (shift % 26))
        else:
            result += char
    return result

def caesar_cipher(text: str, shift: int) -> str:
    result = []
    for char in text:
        if char.isalpha():
            value = ord(char) - 65 # A=0, Z=25
            shifted_value = value + shift
            result.append(chr(int(shifted_value) + 65)) # map value back to char
        else:
            result.append(char)
    return ''.join(result)

