def fibonacci(n: int) -> int:
    """Return the nth Fibonacci number.

    fibonacci(0) = 0
    fibonacci(1) = 1
    fibonacci(n) = fibonacci(n-1) + fibonacci(n-2)"""
    def helper(current: int, count: int):
        if count == 1:
            return current
        result = helper(current + 1, count - 1) + helper(current + 2, count - 2)
        return result

    return helper(0, n)
